  .actions { grid-column: 2; margin-top: .25rem; }
  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }
  button:disabled { background: #9aa5b1; cursor: wait; }
