<main>
  <h1>ScoreArena</h1>
  <p class="sub">桌面规则游戏与赛事管理</p>

  <h2>创建公开房间</h2>
  <form id="room-form" novalidate>
    <div class="field">
      <label for="name">房间名称</label>
      <input id="name" name="name" type="text" autocomplete="off"
             placeholder="1–40 个字符，首尾空白会被去掉" required>
      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>
    </div>
    <div class="field">
      <label for="game">游戏规则</label>
      <select id="game" name="game" required>
        <option value="" selected>请选择游戏规则…</option>
        <option value="gomoku">五子棋（gomoku）</option>
        <option value="ludo">飞行棋（ludo）</option>
      </select>
    </div>
    <div class="field">
      <label for="capacity">人数上限</label>
      <select id="capacity" name="capacity" required disabled>
        <option value="" selected>请先选择游戏规则</option>
      </select>
      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
    </div>
    <div class="field">
      <label for="turnSeconds">每步时间限制</label>
      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric"
             placeholder="秒，0 表示不限时" required>
      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
    </div>
    <div class="field">
      <div></div>
      <div class="actions">
        <button type="submit" id="submit">创建房间</button>
      </div>
    </div>
    <p class="msg" id="form-msg" role="alert"></p>
  </form>

  <h2>房间列表</h2>
  <div id="list-area">
    <p class="empty" id="empty-tip">还没有房间记录。</p>
  </div>

  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
</main>

<script>
(function () {
  var form = document.getElementById('room-form');
  var gameSel = document.getElementById('game');
  var capSel = document.getElementById('capacity');
  var capHint = document.getElementById('capacity-hint');
  var submitBtn = document.getElementById('submit');
  var formMsg = document.getElementById('form-msg');
  var listArea = document.getElementById('list-area');
  var emptyTip = document.getElementById('empty-tip');

  var GAME_LABELS = { gomoku: '五子棋', ludo: '飞行棋' };
  var STATUS_LABELS = { waiting: '未开始' };

  // 按所选规则重建人数上限选项。
  function syncCapacity() {
    var game = gameSel.value;
    var prev = capSel.value;
    capSel.innerHTML = '';
    if (game === 'gomoku') {
      capSel.disabled = false;
      addOption('', '固定 2 人');
      addOption('2', '2 人');
      capSel.value = '2';
      capHint.textContent = '五子棋人数上限固定为 2 人。';
    } else if (game === 'ludo') {
      capSel.disabled = false;
      addOption('', '请选择人数上限…');
      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
    } else {
      capSel.disabled = true;
      addOption('', '请先选择游戏规则');
      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
    }
  }

  function addOption(value, text) {
    var opt = document.createElement('option');
    opt.value = value;
    opt.textContent = text;
    capSel.appendChild(opt);
  }

  gameSel.addEventListener('change', syncCapacity);

  function showMessage(kind, text) {
    formMsg.className = 'msg show ' + kind;
    formMsg.textContent = text;
  }
  function clearMessage() {
    formMsg.className = 'msg';
    formMsg.textContent = '';
  }

  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：
  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。
  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。
  var EDGE_SPACE = '[\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]';
  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');
  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');
  function trimName(value) {
    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');
  }

  // 与服务端一致的提交前校验；服务端仍会再次校验。
  function validate(payload) {
    var nameLen = Array.from(trimName(payload.name)).length;
    if (nameLen === 0) return '房间名称不能为空。';
    if (nameLen > 40) return '房间名称去掉首尾空白后不能超过 40 个字符。';
    if (payload.game !== 'gomoku' && payload.game !== 'ludo') return '请选择游戏规则。';
    if (payload.game === 'gomoku' && payload.capacity !== 2) return '五子棋的人数上限固定为 2 人。';
    if (payload.game === 'ludo' && !(payload.capacity >= 2 && payload.capacity <= 4)) {
      return '飞行棋的人数上限必须为 2 至 4 人。';
    }
    var t = payload.turnSeconds;
    if (t !== 0 && !(Number.isInteger(t) && t >= 10 && t <= 600)) {
      return '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。';
    }
    return null;
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    clearMessage();

    var nameInput = document.getElementById('name');
    var turnInput = document.getElementById('turnSeconds');
    var turnRaw = turnInput.value.trim();
    var payload = {
      name: nameInput.value,
      game: gameSel.value,
      capacity: capSel.value === '' ? null : parseInt(capSel.value, 10),
      turnSeconds: turnRaw === '' ? null : Number(turnRaw)
    };

    // 漏填要明确报错，绝不补默认值；名称只含会被去掉的首尾空白时同样视为空。
    if (trimName(payload.name) === '') return showMessage('error', '房间名称不能为空。'), false;
    if (!payload.game) return showMessage('error', '请选择游戏规则。'), false;
    if (payload.capacity === null) return showMessage('error', '请选择人数上限。'), false;
    if (turnRaw === '') return showMessage('error', '请填写每步时间限制（0 表示不限时）。'), false;
    if (!/^-?\d+$/.test(turnRaw)) return showMessage('error', '时间限制必须是整数秒，不能含小数。'), false;

    var problem = validate({
      name: payload.name,
      game: payload.game,
      capacity: payload.capacity,
      turnSeconds: Number(turnRaw)
    });
    if (problem) { showMessage('error', problem); return; }

    payload.turnSeconds = Number(turnRaw);
    submit(payload);
  });

  function submit(payload) {
    submitBtn.disabled = true;
    fetch('/api/rooms', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }).then(function (resp) {
      return resp.json().catch(function () { return {}; }).then(function (data) {
        return { ok: resp.ok, status: resp.status, data: data };
      });
    }).then(function (result) {
      if (result.ok && result.status === 201) {
        showMessage('ok', '房间已创建，编号：' + result.data.id);
        form.reset();
        syncCapacity();
        return loadRooms();
      }
      // 创建失败：保留填写内容，仅显示原因。
      var reason = result.data && result.data.error ? result.data.error
                 : ('创建失败（HTTP ' + result.status + '）');
      showMessage('error', reason);
    }).catch(function () {
      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
    }).finally(function () {
      submitBtn.disabled = false;
    });
  }

  function formatTime(iso) {
    var d = new Date(iso);
    if (isNaN(d.getTime())) return iso;
    var pad = function (n) { return String(n).padStart(2, '0'); };
    var text = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    return { text: text, title: iso };
  }

  // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。
  // 不按创建表单的规则重新判定历史记录：对象带多少附加字段都照常展示，
  // 也不检查其字段是否完整或合法（各单元格沿用现有兜底显示）。
  function isRoomRecord(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
  }

  function appendSkipNotice(skipped, allSkipped) {
    var p = document.createElement('p');
    p.className = 'skip-notice';
    if (allSkipped) {
      p.textContent = '没有可展示的房间。本次返回的房间记录中有 ' + skipped +
        ' 条无法作为房间显示，已全部跳过；原始数据仍保留在服务端，未被删除或改写。';
    } else {
      p.textContent = '有 ' + skipped + ' 条房间记录无法作为房间显示，已跳过；' +
        '原始数据仍保留在服务端，未被删除或改写。';
    }
    listArea.appendChild(p);
  }

  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
  // 异常，仍走各列原有的展示与兜底。
  var BAD_FIELD_TEXT = '字段格式异常';
  function isAbnormalField(value) {
    return value !== null && typeof value === 'object';
  }
  function markBadCell(td) {
    td.textContent = BAD_FIELD_TEXT;
  }

  // 逐单元格渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
  function buildRoomRow(r) {
    var tr = document.createElement('tr');

    var tdId = document.createElement('td');
    tdId.className = 'id';
    if (isAbnormalField(r.id)) markBadCell(tdId);
    else tdId.textContent = r.id || '';
    tr.appendChild(tdId);

    var tdName = document.createElement('td');
    if (isAbnormalField(r.name)) markBadCell(tdName);
    else tdName.textContent = r.name || '';
    tr.appendChild(tdName);

    var tdGame = document.createElement('td');
    if (isAbnormalField(r.game)) markBadCell(tdGame);
    else tdGame.textContent = GAME_LABELS[r.game] || r.game || '';
    tr.appendChild(tdGame);

    var tdCap = document.createElement('td');
    if (isAbnormalField(r.capacity)) markBadCell(tdCap);
    else tdCap.textContent = (r.capacity != null ? r.capacity : '') + ' 人';
    tr.appendChild(tdCap);

    var tdTurn = document.createElement('td');
    if (isAbnormalField(r.turnSeconds)) {
      markBadCell(tdTurn);
    } else if (r.turnSeconds === 0) {
      tdTurn.textContent = '不限时';
    } else {
      tdTurn.textContent = r.turnSeconds + ' 秒';
    }
    tr.appendChild(tdTurn);

    var tdStatus = document.createElement('td');
    var badge = document.createElement('span');
    badge.className = 'badge';
    if (isAbnormalField(r.status)) badge.textContent = BAD_FIELD_TEXT;
    else badge.textContent = STATUS_LABELS[r.status] || r.status || '';
    tdStatus.appendChild(badge);
    tr.appendChild(tdStatus);

    var tdTime = document.createElement('td');
    if (isAbnormalField(r.createdAt)) {
      // 异常创建时间只显示异常文案，不附加日期悬浮说明（不设置 title）。
      markBadCell(tdTime);
    } else {
      var t = formatTime(r.createdAt || '');
      tdTime.textContent = t.text;
      tdTime.title = t.title;
    }
    tr.appendChild(tdTime);

    return tr;
  }

  function renderRooms(rooms) {
    listArea.innerHTML = '';

    var validRooms = [];
    var skipped = 0;
    rooms.forEach(function (r) {
      if (isRoomRecord(r)) validRooms.push(r);
      else skipped++;
    });

    if (!validRooms.length) {
      if (skipped > 0) {
        appendSkipNotice(skipped, true);
      } else {
        var pEmpty = document.createElement('p');
        pEmpty.className = 'empty';
        pEmpty.textContent = '还没有房间记录。';
        listArea.appendChild(pEmpty);
      }
      return;
    }

    if (skipped > 0) appendSkipNotice(skipped, false);

    var table = document.createElement('table');
    table.innerHTML =
      '<thead><tr>' +
      '<th>房间编号</th><th>名称</th><th>规则</th><th>人数上限</th>' +
      '<th>时间限制</th><th>状态</th><th>创建时间</th>' +
      '</tr></thead>';
    var tbody = document.createElement('tbody');
    validRooms.forEach(function (r) {
      tbody.appendChild(buildRoomRow(r));
    });
    table.appendChild(tbody);
    listArea.appendChild(table);
  }

  // 列表查询序号：每次发起查询递增，只有当前最新一次查询的结果
  // （无论成功还是失败）允许更新列表区域；较早查询后返回的结果一律忽略，
  // 防止旧数据覆盖新查询已展示的列表。
  var listQuerySeq = 0;

  function loadRooms() {
    var seq = ++listQuerySeq;
    return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
      .then(function (resp) {
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        return resp.json();
      })
      .then(function (data) {
        if (seq !== listQuerySeq) return;
        var rooms = Array.isArray(data && data.rooms) ? data.rooms : [];
        renderRooms(rooms);
      })
      .catch(function () {
        if (seq !== listQuerySeq) return;
        listArea.innerHTML = '';
        var p = document.createElement('p');
        p.className = 'list-error';
        p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
        listArea.appendChild(p);
      });
  }

  syncCapacity();
  loadRooms();
})();
</script>
